  try:
   p=subprocess.run(args,stdin=subprocess.DEVNULL,stdout=subprocess.PIPE,stderr=subprocess.PIPE,check=False,timeout=15,env={'LC_ALL':'C','PATH':'/usr/bin:/bin'})
   commands.append({'unit':unit,'name':name,'argv':args,'returncode':p.returncode,'stdout_b64':base64.b64encode(p.stdout).decode('ascii'),'stderr_b64':base64.b64encode(p.stderr).decode('ascii'),'stdout_utf8':p.stdout.decode('utf-8','backslashreplace'),'stderr_utf8':p.stderr.decode('utf-8','backslashreplace')})
  except Exception as e:commands.append({'unit':unit,'name':name,'argv':args,'exception':type(e).__name__+': '+str(e)})
 args=['/usr/bin/systemctl','cat',unit]
 try:
  p=subprocess.run(args,stdin=subprocess.DEVNULL,stdout=subprocess.PIPE,stderr=subprocess.PIPE,check=False,timeout=15,env={'LC_ALL':'C','PATH':'/usr/bin:/bin'})
  commands.append({'unit':unit,'name':'cat_unit','argv':args,'returncode':p.returncode,'stdout_b64':base64.b64encode(p.stdout).decode('ascii'),'stderr_b64':base64.b64encode(p.stderr).decode('ascii'),'stdout_utf8':p.stdout.decode('utf-8','backslashreplace'),'stderr_utf8':p.stderr.decode('utf-8','backslashreplace')})
 except Exception as e:commands.append({'unit':unit,'name':'cat_unit','argv':args,'exception':type(e).__name__+': '+str(e)})
