 try:
  s=os.lstat(guard); fd=os.open(guard,os.O_RDONLY|os.O_NOFOLLOW); data=os.read(fd,65537); os.close(fd)
  out['files'][guard]={'kind':'symlink' if stat.S_ISLNK(s.st_mode) else 'regular' if stat.S_ISREG(s.st_mode) else 'other','uid':s.st_uid,'gid':s.st_gid,'mode':oct(stat.S_IMODE(s.st_mode)),'device':s.st_dev,'inode':s.st_ino,'size':s.st_size,'sha256':hashlib.sha256(data).hexdigest(),'bytes_b64':base64.b64encode(data).decode('ascii'),'bytes_utf8':data.decode('utf-8','backslashreplace')}
 except FileNotFoundError:out['files'][guard]={'state':'absent'}
 except Exception as e:out['files'][guard]={'error':type(e).__name__+': '+str(e)}
for pth in ['/var/lib/vst-runner/private/snapshot-transaction-incomplete.json','/var/lib/vst-runner/private/fence-ledger.json','/var/lib/vst-runner/private/store.sqlite3']:
 try:
